'use strict';

// SAM v2 strict spec of one payment's lifecycle in src/host.impl.ts.
// status 'none' = the payment id was never authorised.
// pending = authorisation requests sent and not yet answered by the provider.
// COMPLETE answers one pending request (outcome ok | failed).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_REQUESTS = 3;
const INITIAL_STATE = { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending: 0 };
const MAX_AUTHORIZED = 3;
const AMOUNTS = [0, 1, 2, 3, 4].map((amount) => ({ amount }));
const isUnit = (a) => a === 1 || a === 2;
const isCaptureAmount = (a) => a === 1 || a === 2 || a === 3;
const ALL = ['status', 'authorized', 'captured', 'refunded', 'requests', 'pending'];
const keep = (unchanged, ...written) => unchanged(...ALL.filter((k) => !written.includes(k)));

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      authorized: { type: 'number' },
      captured: { type: 'number' },
      refunded: { type: 'number' },
      requests: { type: 'number' },
      pending: { type: 'number' },
    },
    actions: {
      AUTHORIZE: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS },
      TIMED_OUT: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CAPTURE: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS },
      VOID: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      INCREASE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      REFUND: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS },
      COMPLETE: { action: (data = {}) => ({ ...data }), schema: { outcome: 'string' }, domain: [{ outcome: 'ok' }, { outcome: 'failed' }] },
    },
    acceptors: {
      AUTHORIZE: (model) => (p, { reject, next, unchanged }) => {
        if (!isUnit(p.amount)) return reject('bad-amount');
        if (model.status !== 'none') return reject('exists');
        next.status = 'authorizing';
        next.authorized = p.amount;
        next.requests = 1;
        next.pending = 1;
        keep(unchanged, 'status', 'authorized', 'requests', 'pending');
      },
      TIMED_OUT: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'authorizing') return reject('not-authorizing');
        if (model.requests >= MAX_REQUESTS) {
          next.status = 'failed';
          keep(unchanged, 'status');
        } else {
          next.requests = model.requests + 1;
          next.pending = model.pending + 1;
          keep(unchanged, 'requests', 'pending');
        }
      },
      CAPTURE: (model) => (p, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown');
        if (!isCaptureAmount(p.amount)) return reject('bad-amount');
        if (model.status !== 'authorized') return reject('not-authorized');
        if (p.amount > model.authorized) return reject('exceeds-authorized');
        next.captured = p.amount;
        next.status = 'captured';
        keep(unchanged, 'captured', 'status');
      },
      VOID: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-voidable');
        next.status = 'voided';
        keep(unchanged, 'status');
      },
      INCREASE: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-increasable');
        if (model.authorized >= MAX_AUTHORIZED) return reject('at-max-authorized');
        next.authorized = model.authorized + 1;
        keep(unchanged, 'authorized');
      },
      EXPIRE: (model) => (p, { reject, next, unchanged }) => {
        if (model.status !== 'authorized' || model.captured !== 0) return reject('not-expirable');
        next.status = 'expired';
        keep(unchanged, 'status');
      },
      REFUND: (model) => (p, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown');
        if (!isUnit(p.amount)) return reject('bad-amount');
        if (model.status !== 'captured') return reject('not-captured');
        if (model.refunded + p.amount > model.captured) return reject('exceeds-captured');
        const refunded = model.refunded + p.amount;
        next.refunded = refunded;
        if (refunded === model.captured) { next.status = 'refunded'; keep(unchanged, 'refunded', 'status'); }
        else keep(unchanged, 'refunded');
      },
      COMPLETE: (model) => (p, { reject, next, unchanged }) => {
        if (model.pending === 0) return reject('no-pending-request');
        next.pending = model.pending - 1;
        if (model.status === 'authorizing') {
          next.status = p.outcome === 'ok' ? 'authorized' : 'declined';
          keep(unchanged, 'pending', 'status');
        } else keep(unchanged, 'pending');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  AUTHORIZE: (data = {}) => intents.AUTHORIZE(data),
  TIMED_OUT: (data = {}) => intents.TIMED_OUT(data),
  CAPTURE: (data = {}) => intents.CAPTURE(data),
  VOID: (data = {}) => intents.VOID(data),
  INCREASE: (data = {}) => intents.INCREASE(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  REFUND: (data = {}) => intents.REFUND(data),
  COMPLETE: (data = {}) => intents.COMPLETE(data),
};

module.exports = { instance, init, actions, getState, setState };
